// Shared DFA financial utilities (inlined into n8n Code nodes)
const SEC_UA = 'DamodaranAnalystSystem/2.0 contact@goevolo.com';

function normName(v) {
  return String(v || '').toLowerCase().replace(/[^a-z0-9]/g, '');
}

function tagRows(facts, tags) {
  for (const tag of tags) {
    const fact = facts[tag];
    if (!fact?.units) continue;
    const rows = Object.values(fact.units).flat().filter((r) => r && r.val !== undefined);
    if (rows.length) return { tag, rows };
  }
  return { tag: tags[0], rows: [] };
}

function latestAnnualRow(rows, fy) {
  return rows
    .filter((r) => r.form === '10-K' && Number(r.fy) === Number(fy))
    .sort((a, b) => String(a.end || '').localeCompare(String(b.end || '')) || String(a.filed || '').localeCompare(String(b.filed || '')))
    .at(-1) || null;
}

function latestQuarterRows(rows) {
  const qrows = rows.filter((r) => r.form === '10-Q' && r.fy && r.fp)
    .sort((a, b) => String(a.end || '').localeCompare(String(b.end || '')) || String(a.filed || '').localeCompare(String(b.filed || '')));
  const uniq = [];
  for (const row of qrows) {
    const key = `${row.fy}-${row.fp}`;
    if (!uniq.some((p) => p.key === key)) uniq.push({ key, fy: row.fy, fp: row.fp, end: row.end, filed: row.filed });
  }
  return uniq;
}

function compactFacts(usGaapAll) {
  const supported = [
    'RevenueFromContractWithCustomerExcludingAssessedTax', 'Revenues', 'SalesRevenueNet',
    'GrossProfit', 'OperatingIncomeLoss', 'NetIncomeLoss', 'ProfitLoss',
    'NetCashProvidedByUsedInOperatingActivities', 'NetCashProvidedByUsedInOperatingActivitiesContinuingOperations',
    'PaymentsToAcquirePropertyPlantAndEquipment', 'PaymentsToAcquireProductiveAssets',
    'LongTermDebtAndFinanceLeaseObligationsNoncurrent', 'LongTermDebtNoncurrent', 'LongTermDebtAndFinanceLeaseObligationsCurrent',
    'AssetsCurrent', 'LiabilitiesCurrent', 'InterestExpenseNonOperating', 'InterestExpense',
    'EarningsPerShareDiluted', 'DepreciationDepletionAndAmortization', 'DepreciationDepletionAndAmortizationExpense', 'DepreciationAndAmortization',
    'StockholdersEquity', 'StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest',
    'Assets', 'Liabilities', 'CashAndCashEquivalentsAtCarryingValue', 'ShortTermBorrowings'
  ];
  const out = {};
  for (const tag of supported) {
    const fact = usGaapAll[tag];
    if (!fact?.units) continue;
    const units = {};
    for (const [unitName, rows] of Object.entries(fact.units)) {
      if (!Array.isArray(rows)) continue;
      const compact = rows
        .filter((r) => r && r.val !== undefined && ['10-K', '10-Q'].includes(r.form))
        .sort((a, b) => String(a.filed || '').localeCompare(String(b.filed || '')) || String(a.end || '').localeCompare(String(b.end || '')))
        .slice(-20)
        .map((r) => ({ end: r.end, val: r.val, fy: r.fy, fp: r.fp, form: r.form, filed: r.filed, frame: r.frame }));
      if (compact.length) units[unitName] = compact;
    }
    if (Object.keys(units).length) out[tag] = { label: fact.label, units };
  }
  return out;
}

function resolveCikFromDirectory(directory, companyName, ticker) {
  const rows = Array.isArray(directory) ? directory : Object.values(directory || {});
  const nameNorm = normName(companyName);
  const tickerNorm = normName(ticker);
  function score(row) {
    const title = row.title || row.name || '';
    const rowTicker = row.ticker || '';
    const titleNorm = normName(title);
    const rowTickerNorm = normName(rowTicker);
    let points = 0;
    if (tickerNorm && rowTickerNorm === tickerNorm) points += 120;
    if (titleNorm === nameNorm) points += 100;
    if (nameNorm && titleNorm.startsWith(nameNorm)) points += 70;
    if (nameNorm && titleNorm.includes(nameNorm)) points += 45;
    return points;
  }
  const ranked = rows
    .filter((row) => row && (row.title || row.name) && (row.cik_str || row.cik))
    .map((row) => ({ row, score: score(row) }))
    .filter((e) => e.score > 0)
    .sort((a, b) => b.score - a.score);
  const best = ranked[0]?.row || null;
  const rawCik = best?.cik_str || best?.cik || null;
  const cik = rawCik ? String(rawCik).padStart(10, '0') : null;
  return { best, cik, ranked };
}

function metricFromFacts(facts, metric, fy) {
  const map = {
    revenue: ['RevenueFromContractWithCustomerExcludingAssessedTax', 'Revenues', 'SalesRevenueNet'],
    gross_profit: ['GrossProfit'],
    operating_income: ['OperatingIncomeLoss'],
    net_income: ['NetIncomeLoss', 'ProfitLoss'],
    operating_cash_flow: ['NetCashProvidedByUsedInOperatingActivities', 'NetCashProvidedByUsedInOperatingActivitiesContinuingOperations'],
    capex: ['PaymentsToAcquirePropertyPlantAndEquipment', 'PaymentsToAcquireProductiveAssets'],
    long_term_debt: ['LongTermDebtAndFinanceLeaseObligationsNoncurrent', 'LongTermDebtNoncurrent'],
    current_assets: ['AssetsCurrent'],
    current_liabilities: ['LiabilitiesCurrent'],
    interest_expense: ['InterestExpenseNonOperating', 'InterestExpense'],
    equity: ['StockholdersEquity', 'StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest'],
    assets: ['Assets'],
    cash: ['CashAndCashEquivalentsAtCarryingValue'],
    depreciation: ['DepreciationDepletionAndAmortization', 'DepreciationDepletionAndAmortizationExpense', 'DepreciationAndAmortization']
  };
  const found = tagRows(facts, map[metric] || [metric]);
  const row = latestAnnualRow(found.rows, fy);
  return row ? Number(row.val) : null;
}

function computeEntityMetrics(facts, sourceMeta) {
  const years = [2025, 2024, 2023];
  const latestFy = years.find((fy) => metricFromFacts(facts, 'revenue', fy) !== null) || years[1];
  const revenue = metricFromFacts(facts, 'revenue', latestFy);
  const gross = metricFromFacts(facts, 'gross_profit', latestFy);
  const op = metricFromFacts(facts, 'operating_income', latestFy);
  const net = metricFromFacts(facts, 'net_income', latestFy);
  const ocf = metricFromFacts(facts, 'operating_cash_flow', latestFy);
  const capex = metricFromFacts(facts, 'capex', latestFy);
  const ca = metricFromFacts(facts, 'current_assets', latestFy);
  const cl = metricFromFacts(facts, 'current_liabilities', latestFy);
  const interest = metricFromFacts(facts, 'interest_expense', latestFy);
  const debt = metricFromFacts(facts, 'long_term_debt', latestFy);
  const equity = metricFromFacts(facts, 'equity', latestFy);
  const assets = metricFromFacts(facts, 'assets', latestFy);
  const cash = metricFromFacts(facts, 'cash', latestFy);
  const dep = metricFromFacts(facts, 'depreciation', latestFy);
  const revY1 = metricFromFacts(facts, 'revenue', latestFy - 1);
  const revY3 = metricFromFacts(facts, 'revenue', latestFy - 3);
  const fcf = ocf !== null && capex !== null ? ocf - capex : null;
  const ebitda = op !== null && dep !== null ? op + dep : null;
  const safeDiv = (a, b) => (a !== null && b !== null && b !== 0 ? a / b : null);
  return {
    period: `FY${latestFy}`,
    revenue,
    gross_margin: safeDiv(gross, revenue),
    operating_margin: safeDiv(op, revenue),
    net_margin: safeDiv(net, revenue),
    ebitda_margin: safeDiv(ebitda, revenue),
    fcf_margin: safeDiv(fcf, revenue),
    current_ratio: safeDiv(ca, cl),
    debt_to_equity: safeDiv(debt, equity),
    interest_coverage: safeDiv(op, interest),
    roce: safeDiv(op, assets && cl !== null ? assets - cl : null),
    asset_turnover: safeDiv(revenue, assets),
    yoy_revenue_growth: safeDiv(revenue && revY1 ? revenue - revY1 : null, revY1),
    revenue_cagr_3y: revY3 && revenue && revY3 > 0 ? Math.pow(revenue / revY3, 1 / 3) - 1 : null,
    net_debt_ebitda: ebitda && debt !== null && cash !== null && ebitda !== 0 ? (debt - cash) / ebitda : null,
    source_meta: sourceMeta
  };
}

function fmtMetric(v, asPct = false) {
  if (v === null || v === undefined || Number.isNaN(v)) return 'N/A';
  if (asPct) return `${(v * 100).toFixed(1)}%`;
  if (Math.abs(v) >= 1e9) return `${(v / 1e9).toFixed(2)}B USD`;
  if (Math.abs(v) >= 1e6) return `${(v / 1e6).toFixed(1)}M USD`;
  return `${Number(v).toLocaleString('en-US')} USD`;
}

function peerDefaults(industry) {
  const key = String(industry || '').toLowerCase();
  const defaults = {
    technology: ['Microsoft', 'Alphabet', 'Meta Platforms', 'Amazon', 'NVIDIA'],
    saas: ['Salesforce', 'Adobe', 'ServiceNow', 'Atlassian', 'Workday'],
    retail: ['Walmart', 'Costco', 'Target', 'Amazon', 'Home Depot'],
    banking: ['JPMorgan Chase', 'Bank of America', 'Wells Fargo', 'Citigroup', 'Goldman Sachs'],
    healthcare: ['UnitedHealth Group', 'HCA Healthcare', 'Elevance Health', 'CVS Health', 'Humana'],
    manufacturing: ['General Electric', 'Honeywell', 'Caterpillar', '3M', 'Siemens'],
    gaming: ['Electronic Arts', 'Take-Two Interactive', 'Roblox', 'Nintendo', 'Sony'],
    media: ['Disney', 'Netflix', 'Comcast', 'Warner Bros. Discovery', 'Paramount Global']
  };
  const match = Object.keys(defaults).find((k) => key.includes(k)) || 'technology';
  return defaults[match];
}

function parsePeerList(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  return String(raw).split(/[,;\n|]/).map((s) => s.trim()).filter(Boolean);
}

function claudeBaseSystem(inputs, expert) {
  return `You are an AI financial analyst who thinks like Aswath Damodaran. Evidence first. Every figure must come from the provided JSON only. Never fabricate numbers. If data is missing, write N/A and explain why. Show formulas for computed metrics. Do not use templating placeholders or curly-brace variables. Industry lens: ${expert?.name || inputs.expert_pref || 'industry expert'}. Executive audience: ${inputs.exec_type || 'executive'}. Service provider: ${inputs.service_provider || 'MY COMPANY'}.`;
}

function parseClaudeJson(response) {
  const content = response?.content || [];
  const text = content.map((p) => p.text || '').join('\n').trim() || JSON.stringify(response);
  try { return JSON.parse(text); } catch (e) {}
  const match = text.match(/\{[\s\S]*\}/);
  if (match) { try { return JSON.parse(match[0]); } catch (e) {} }
  return { _raw: text };
}

const state = items[0]?.json?.state || items[0]?.json || {};
const now = new Date().toISOString();
const industry = String(state.inputs?.industry || '').toLowerCase();
const company = state.entity?.legal_name || state.inputs?.company_name || 'Company';
const inputPeers = parsePeerList(state.inputs?.peer_list || state.inputs?.advanced_context?.peers || state.inputs?.advanced_context?.known_competitors);
const peerNames = (inputPeers.length ? inputPeers : peerDefaults(industry))
  .filter((name) => normName(name) !== normName(company))
  .slice(0, 3);
const metricLabels = ['Revenue', 'Gross Margin', 'Operating Margin', 'Net Margin', 'FCF Margin', 'Current Ratio', 'YoY Revenue Growth', '3-Year Revenue CAGR', 'Net Debt / EBITDA', 'Interest Coverage', 'ROCE/ROIC', 'Asset Turnover'];

async function secGet(url) {
  return this.helpers.httpRequest({
    method: 'GET',
    url,
    headers: { 'User-Agent': SEC_UA, Accept: 'application/json' },
    json: true,
    timeout: 30000,
  });
}

let directory = state.research?.sec_directory;
if (!directory) {
  directory = await secGet.call(this, 'https://www.sec.gov/files/company_tickers.json');
  state.research = state.research || {};
  state.research.sec_directory = directory;
}

function companyRowFromState() {
  const pb = state.peer_benchmarks?.company_metrics;
  if (pb) return pb;
  const m = state.normalized?.metrics || {};
  function latest(name) {
    const s = m[name] || [];
    return Array.isArray(s) && s.length ? s[s.length - 1] : null;
  }
  const revenue = latest('revenue');
  const fcf = latest('free_cash_flow');
  return {
    name: company,
    role: 'target company',
    metrics: {
      Revenue: revenue ? fmtMetric(revenue.value) : 'N/A',
      'Gross Margin': latest('gross_margin') ? fmtMetric(latest('gross_margin').value, true) : 'N/A',
      'Operating Margin': latest('operating_margin') ? fmtMetric(latest('operating_margin').value, true) : 'N/A',
      'Net Margin': latest('net_margin') ? fmtMetric(latest('net_margin').value, true) : 'N/A',
      'FCF Margin': fcf && revenue ? fmtMetric(fcf.value / revenue.value, true) : 'N/A',
      'Current Ratio': latest('current_ratio') ? Number(latest('current_ratio').value).toFixed(2) : 'N/A',
      'YoY Revenue Growth': 'N/A',
      '3-Year Revenue CAGR': 'N/A',
      'Net Debt / EBITDA': 'N/A',
      'Interest Coverage': 'N/A',
      'ROCE/ROIC': 'N/A',
      'Asset Turnover': 'N/A',
    },
    source_status: 'SEC_NORMALIZED',
    reliability: state.entity?.is_public ? 'HIGH' : 'MEDIUM',
  };
}

const peers = [];
for (let i = 0; i < peerNames.length; i++) {
  const name = peerNames[i];
  const role = i === 0 ? 'best-in-class or scale benchmark' : (i === 1 ? 'close competitor' : 'industry peer');
  let metrics = Object.fromEntries(metricLabels.map((m) => [m, 'N/A']));
  let source_status = 'NO_SEC_MATCH';
  let reliability = 'N/A';
  try {
    const { best, cik } = resolveCikFromDirectory(directory, name, '');
    if (cik) {
      const factsResp = await secGet.call(this, `https://data.sec.gov/api/xbrl/companyfacts/CIK${cik}.json`);
      const usGaap = factsResp?.facts?.['us-gaap'] || {};
      const compact = compactFacts(usGaap);
      const computed = computeEntityMetrics(compact, { source_name: 'SEC EDGAR Company Facts XBRL', cik, legal_name: best?.title || name, fetched_at: now });
      metrics = {
        Revenue: fmtMetric(computed.revenue),
        'Gross Margin': fmtMetric(computed.gross_margin, true),
        'Operating Margin': fmtMetric(computed.operating_margin, true),
        'Net Margin': fmtMetric(computed.net_margin, true),
        'FCF Margin': fmtMetric(computed.fcf_margin, true),
        'Current Ratio': fmtMetric(computed.current_ratio),
        'YoY Revenue Growth': fmtMetric(computed.yoy_revenue_growth, true),
        '3-Year Revenue CAGR': fmtMetric(computed.revenue_cagr_3y, true),
        'Net Debt / EBITDA': computed.net_debt_ebitda !== null ? Number(computed.net_debt_ebitda).toFixed(2) : 'N/A',
        'Interest Coverage': fmtMetric(computed.interest_coverage),
        'ROCE/ROIC': fmtMetric(computed.roce, true),
        'Asset Turnover': fmtMetric(computed.asset_turnover),
      };
      source_status = 'SEC_PEER_FACTS_OK';
      reliability = 'HIGH';
    }
  } catch (e) {
    source_status = `SEC_FETCH_ERROR: ${e.message || e}`;
    reliability = 'LOW';
  }
  peers.push({ name, role, ticker: null, metrics, source_status, reliability });
}

const companyRow = companyRowFromState();
const columns = ['Entity', 'Role', ...metricLabels];
const allRows = [companyRow, ...peers];
const markdown = [
  '## Section 3: Peer Comparison & Benchmarking',
  '',
  `Data fetched at runtime: ${now}`,
  '',
  '| ' + columns.join(' | ') + ' |',
  '|---|' + columns.slice(1).map(() => '---').join('|') + '|',
  ...allRows.map((row) => `| ${row.name} | ${row.role} | ${metricLabels.map((m) => row.metrics[m]).join(' | ')} |`),
  '',
  'Interpretation: peer metrics are computed from live SEC EDGAR company facts at execution time. Cells remain N/A when the peer cannot be resolved to a US public CIK or required XBRL tags are missing.',
].join('\n');

state.peer_benchmarks = {
  generated_at: now,
  selection_rule: inputPeers.length ? 'user_provided_peers' : 'industry_default_selection',
  peers,
  company_row: companyRow,
  markdown,
};
state.sections = state.sections || {};
state.sections.s3_benchmarks = markdown;
state.audit_log = state.audit_log || [];
state.audit_log.push({
  timestamp: now,
  workflow_name: 'WF_PEER_BENCHMARKS',
  status: peers.some((p) => p.source_status === 'SEC_PEER_FACTS_OK') ? 'OK' : 'WARN',
  message: `Peer benchmark section built with ${peers.filter((p) => p.source_status === 'SEC_PEER_FACTS_OK').length}/${peers.length} SEC-backed peers.`,
});
return [{ json: state }];

const state = items[0]?.json?.state || items[0]?.json || {};
const now = new Date().toISOString();
const industry = String(state.inputs?.industry || '').toLowerCase();
const company = state.entity?.legal_name || state.inputs?.company_name || 'Company';
const inputPeers = Array.isArray(state.inputs?.peer_list) ? state.inputs.peer_list : [];
const defaults = {
  technology: ['Microsoft','Alphabet','Meta Platforms','Amazon','NVIDIA'],
  saas: ['Salesforce','Adobe','ServiceNow','Atlassian','Workday'],
  retail: ['Walmart','Costco','Target','Amazon','Home Depot'],
  banking: ['JPMorgan Chase','Bank of America','Wells Fargo','Citigroup','Goldman Sachs'],
  healthcare: ['UnitedHealth Group','HCA Healthcare','Elevance Health','CVS Health','Humana'],
  manufacturing: ['Toyota','General Electric','Honeywell','Caterpillar','Siemens'],
  gaming: ['Electronic Arts','Take-Two Interactive','Roblox','Nintendo','Sony'],
  media: ['Disney','Netflix','Comcast','Warner Bros. Discovery','Paramount Global']
};
const matchKey = Object.keys(defaults).find((key) => industry.includes(key)) || 'technology';
const peerNames = (inputPeers.length ? inputPeers : defaults[matchKey]).slice(0, 6);
function latestMetric(name) {
  const series = state.normalized?.metrics?.[name] || [];
  return Array.isArray(series) && series.length ? series[series.length - 1] : null;
}
function ratio(name) {
  const item = latestMetric(name);
  return item ? item.value : null;
}
const companyMetrics = {
  revenue: latestMetric('revenue')?.value ?? null,
  gross_margin: ratio('gross_margin'),
  operating_margin: ratio('operating_margin'),
  net_margin: ratio('net_margin'),
  fcf_margin: latestMetric('free_cash_flow') && latestMetric('revenue')?.value ? latestMetric('free_cash_flow').value / latestMetric('revenue').value : null,
  current_ratio: ratio('current_ratio')
};
const metricLabels = ['Revenue','Gross Margin','Operating Margin','Net Margin','FCF Margin','Current Ratio','YoY Revenue Growth','3-Year Revenue CAGR','Net Debt / EBITDA','Interest Coverage','ROCE/ROIC','Asset Turnover'];
const peers = peerNames.map((name, index) => ({
  name,
  role: index === 0 ? 'best-in-class or scale benchmark' : (index === 1 ? 'close competitor' : 'industry peer'),
  metrics: Object.fromEntries(metricLabels.map((metric) => [metric, 'N/A - peer SEC metric fetch not yet available in this run'])),
  source_status: 'PENDING_PEER_SEC_FACTS',
  reliability: 'LOW_UNTIL_PEER_FACTS_FETCHED'
}));
const companyRow = { name: company, role: 'target company', metrics: {
  Revenue: companyMetrics.revenue ?? 'N/A',
  'Gross Margin': companyMetrics.gross_margin ?? 'N/A',
  'Operating Margin': companyMetrics.operating_margin ?? 'N/A',
  'Net Margin': companyMetrics.net_margin ?? 'N/A',
  'FCF Margin': companyMetrics.fcf_margin ?? 'N/A',
  'Current Ratio': companyMetrics.current_ratio ?? 'N/A',
  'YoY Revenue Growth': 'N/A - quarterly peer/company comparison requires expanded quarterly normalization',
  '3-Year Revenue CAGR': 'N/A - requires three comparable fiscal-year revenue points',
  'Net Debt / EBITDA': 'N/A - requires cash, debt, EBITDA',
  'Interest Coverage': 'N/A - requires interest expense',
  'ROCE/ROIC': 'N/A - requires capital employed/invested capital',
  'Asset Turnover': 'N/A - requires total assets'
}, source_status: state.normalized?.reliability_map?.public_company_xbrl || 'N/A', reliability: state.entity?.is_public ? 'HIGH_FOR_AVAILABLE_COMPANY_METRICS' : 'LOW' };
const columns = ['Entity','Role',...metricLabels];
const allRows = [companyRow, ...peers];
const markdown = ['## Section 3: Peer Comparison & Benchmarking', '', '| ' + columns.join(' | ') + ' |', '|---|' + columns.slice(1).map(() => '---').join('|') + '|', ...allRows.map((row) => `| ${row.name} | ${row.role} | ${metricLabels.map((metric) => row.metrics[metric]).join(' | ')} |`), '', 'Benchmark interpretation: available target-company metrics are computed from normalized source data. Peer rows are selected and role-labeled now; peer metric cells remain N/A unless peer SEC facts are fetched and normalized in the run. This prevents fake benchmark numbers.'].join('\n');
state.peer_benchmarks = { generated_at: now, selection_rule: inputPeers.length ? 'user_provided_peers' : 'industry_default_selection', peers, company_row: companyRow, markdown };
state.sections = state.sections || {};
state.sections.s3_benchmarks = markdown;
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_PEER_BENCHMARKS', status: 'WARN', message: 'Peer benchmark section created with peer labels; peer metric fetch remains N/A when source facts are unavailable.' });
return [{ json: state }];
